const LINE = 64, SIZE = 8, N = 16;
const perLine = LINE / SIZE;
const lines = {};
for (let i = 0; i < N; i++) {
  const line = Math.floor((i * SIZE) / LINE);
  (lines[line] ||= []).push(i);
}
console.log('counters per 64B line:', perLine);
for (const [line, idxs] of Object.entries(lines)) {
  console.log('line ' + line + ' holds counters ' + idxs.join(','));
}
console.log('0 and 1 share a line:', Math.floor(0/perLine) === Math.floor(1/perLine));
